    SumaIfo(report) {
        let ifo = report.mplaIfo + report.auxIfo + report.boilerIfo + report.otherIfo;
        return ifo;
    }
    SumaMgo(report) {
        let mgo = report.mplaMgo + report.auxMgo + report.boilerMgo + report.ppMgo + report.giMgo + report.otherMgo;
        return mgo;
    }
