class IsBuqueGuard {
    constructor(activatedRoute, _router, _userService) {
        this.activatedRoute = activatedRoute;
        this._router = _router;
        this._userService = _userService;
    }
    canActivate(next, state) {
        // Consultaremos que rol tiene el usuario logeado.
        let identity = this._userService.GetIdentity();
        // rol del buque
        if (identity.role === 'BUQUE') {
            this._router.navigate(['./../application/voyages'], { relativeTo: this.activatedRoute });
            return false;
        }
        else {
            this._router.navigate(['./../application/dashboard'], { relativeTo: this.activatedRoute });
            return false;
        }
    }
}
